INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBNURDT0100000000000000', '*', '', 'pn_contribution_receipt', 'Reçu de contribution exigible (maternelle publique)', 'receipt', 'Q', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","class_name","amount_xaf","payer_name","paid_on","source"]', '2026-10-23T13:11:00+01:00', '2026-10-23T13:11:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBNURDT01F0000000000000', '*', '', 'pn_contribution_receipt', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Reçu de contribution exigible</h2><p>Reçu de <strong>{{payer_name}}</strong> la somme de <strong>{{amount_xaf}} FCFA</strong> au titre de la contribution exigible de l’enfant <strong>{{holder_name}}</strong> ({{class_name}}), année scolaire {{academic_year}}, versée le {{paid_on}} en une tranche.</p><p>Texte de référence : {{source}}.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Reçu n° {{number}} (souche conservée par la direction)</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-23T13:11:00+01:00', NULL, '2026-10-23T13:11:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBNURDT01E0000000000000', '*', '', 'pn_contribution_receipt', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Compulsory contribution receipt</h2><p>Received from <strong>{{payer_name}}</strong> the sum of <strong>{{amount_xaf}} FCFA</strong> as the compulsory contribution for <strong>{{holder_name}}</strong> ({{class_name}}), school year {{academic_year}}, paid on {{paid_on}} in a single instalment.</p><p>Reference text: {{source}}.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Receipt no. {{number}} (counterfoil kept by the head)</p><div>{{qr}}</div><p>Verification: {{verification_url}}</p></body></html>', 1, '2026-10-23T13:11:00+01:00', NULL, '2026-10-23T13:11:00+01:00')
